function Field({label,value,onChange,unit,min=0,max=100000}){const [draft,setDraft]=useState(String(value??'')),[error,setError]=useState(false);useEffect(()=>{setDraft(String(value??''));setError(false)},[value]);function commit(){const n=Number(draft.replace(',','.'));if(!draft.trim()||!Number.isFinite(n)||n<min||n>max){setError(true);return}setError(false);if(n!==value){onChange(n);setDraft(String(value))}}return <label className="field"><span className="field-label">{label}</span><div className={`field-input ${error?'invalid':''}`}><input value={draft} inputMode="decimal" aria-label={label} aria-invalid={error} onChange={e=>{setDraft(e.target.value);setError(false)}} onBlur={commit} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();if(e.key==='Escape'){setDraft(String(value));setError(false);e.currentTarget.blur()}}}/><span>{unit}</span></div>{error&&<small className="field-error">От {min} до {max}</small>}</label>}
