 function chooseTool(t){if(t==='void'){if(p.floors<2){setPage('levels');setToast('Сначала добавьте второй этаж, затем задайте зону второго света.');return}setLevel(2)}setTool(t);setPage('plan');setView('plan');setSelected(null);setPalette(false);if(t==='post')setSection('100x100');else if(t==='beam')setSection('50x200');else if(t==='wall')setSection('50x150')}
